)
insert into public.jp_vocab_examples
 (vocab_id,example_no,example_type,example_jp,example_vi,cloze_jp,answer,difficulty,focus_note,source_type)
select v.id,c.example_no,case c.example_no when 1 then 'exam' else 'business' end,
 c.example_jp,c.example_vi,c.cloze_jp,c.answer,case c.example_no when 1 then 1 else 2 end,
 case c.example_no when 1 then 'Ngữ cảnh JLPT và cấu trúc cơ bản.' else 'Cách dùng thực tế trong công việc.' end,'generated'
from curated c join public.jp_vocab v on v.level='N5' and v.lesson_no=9 and v.word_jp=c.word_jp
on conflict (vocab_id,example_no) do update set example_type=excluded.example_type,
 example_jp=excluded.example_jp,example_vi=excluded.example_vi,cloze_jp=excluded.cloze_jp,
 answer=excluded.answer,difficulty=excluded.difficulty,focus_note=excluded.focus_note,source_type=excluded.source_type;
